from pathlib import Path
import json,shutil
r=Path('/workspace/wall-comparison-2026-11-21');repo=Path('/workspace/Stoneham-spraywall-project');archive=repo/'reviews/2026-11-v9-assistant-reviewed';public=repo/'public/wall/candidates/2026-11-v9';public.mkdir(parents=True,exist_ok=True)
holds=json.loads((archive/'confirmed-geometry.json').read_text())['holds'];oldids={h['id'] for h in json.loads((r/'reference-holds.json').read_text())};new=[h['id'] for h in holds if h['id'] not in oldids]
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stoneham · v9 审核候选</title>
<style>*{box-sizing:border-box}body{margin:0;background:#10150d;color:#edf2e7;font:16px/1.5 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:18px}h1{font-size:25px;margin:0 0 5px}.muted{color:#a6b09f}button,a{font:inherit}button{border:1px solid #46503c;background:#242c1f;color:inherit;border-radius:12px;padding:11px 15px;cursor:pointer}button[aria-pressed=true]{background:#c9ff53;color:#142000}nav{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.canvas{border:1px solid #46503c;border-radius:14px;overflow:hidden;background:#fff}svg{display:block;width:100%;max-height:78vh;touch-action:pinch-zoom}polygon{fill:transparent;stroke:#20ddcd;stroke-width:2;vector-effect:non-scaling-stroke;cursor:pointer}polygon.new{stroke:#ffff23;stroke-width:3}polygon.selected{fill:#c9ff5344;stroke:#ff6583;stroke-width:4}footer{margin-top:16px;color:#a6b09f}a{color:#c9ff53}.info{min-height:28px;margin-top:10px;overflow-wrap:anywhere}.tag{color:#c9ff53;font-size:14px}details{margin-top:16px}button:focus-visible,a:focus-visible{outline:3px solid #f99;outline-offset:3px}@media(max-width:600px){main{padding:12px}button{padding:10px 12px;font-size:14px}h1{font-size:22px}}</style>
<main><div class="tag">ASSISTANT REVIEW · 尚未发布</div><h1>Stoneham 新墙 · 11 月 21 日</h1><div class="muted">852 个点 · 保留 801 个旧 ID · 新增 51 个 · 待处理 0</div>
<nav aria-label="对比与标注"><button id="new" aria-pressed="true">新墙 v9</button><button id="old" aria-pressed="false">旧墙 v8</button><button id="outlines" aria-pressed="true">显示新标注</button><button id="only" aria-pressed="false">只看新增</button><button id="next">下一个新增点</button><button id="fit">整墙</button></nav>
<div class="canvas"><svg id="wall" viewBox="0 0 7292 5514" role="img" aria-label="可切换新旧照片的墙面标注"><image id="photo" width="7292" height="5514" href="__IMAGE__"></image><g id="polygons"></g></svg></div><div id="info" class="info" aria-live="polite">青色：保留旧 ID；黄色：新增点。点击点位查看，或用“下一个新增点”放大逐个浏览。</div>
<footer><a href="__GIF__">打开新旧对比 GIF</a> · <a href="__PREVIEW__">打开清晰预览图</a><details><summary>审核说明</summary><p>本次由 Codex 按你的请求对照片、身份和轮廓做审核，记录明确标为 assistant。全部旧点重跑 SAM2，起始 polygon 线性收缩 20%；修正了嵌在 volume 上的小点误合并、底部脚点和 13 处手动边界。原始建议和逐条决定已保留。这是图片审核候选，正式站及线路数据库尚未更新。</p></details></footer></main>
<script>
const holds=__HOLDS__,newIds=new Set(__NEW_IDS__),newHolds=holds.filter(h=>newIds.has(h.id)),ns='http://www.w3.org/2000/svg',svg=document.getElementById('wall'),photo=document.getElementById('photo'),layer=document.getElementById('polygons');let mode='new',visible=true,only=false,cursor=-1,selected=null;
function draw(){layer.replaceChildren();for(const h of holds){if(!visible||(only&&!newIds.has(h.id)))continue;const p=document.createElementNS(ns,'polygon');p.setAttribute('points',h.polygon.map(([x,y])=>`${x*7292},${y*5514}`).join(' '));p.setAttribute('class',(newIds.has(h.id)?'new ':'')+(selected===h.id?'selected':''));p.dataset.holdId=h.id;p.addEventListener('click',()=>show(h,false));const t=document.createElementNS(ns,'title');t.textContent=(newIds.has(h.id)?'新增点':'保留旧 ID')+' · '+h.id;p.append(t);layer.append(p)}}
function show(h,zoom){selected=h.id;document.getElementById('info').textContent=(newIds.has(h.id)?`新增点 ${newHolds.findIndex(x=>x.id===h.id)+1}/51`:'保留旧 ID')+' · '+h.id+' · assistant 已审核';if(zoom){const xs=h.polygon.map(p=>p[0]*7292),ys=h.polygon.map(p=>p[1]*5514),span=Math.max(700,(Math.max(...xs)-Math.min(...xs))*2.8,(Math.max(...ys)-Math.min(...ys))*2.8),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2;svg.setAttribute('viewBox',`${Math.max(0,Math.min(7292-span,cx-span/2))} ${Math.max(0,Math.min(5514-span,cy-span/2))} ${span} ${span}`)}draw()}
function setMode(value){mode=value;photo.setAttribute('href',mode==='new'?'__IMAGE__':'__REFERENCE__');for(const key of ['new','old'])document.getElementById(key).setAttribute('aria-pressed',String(mode===key))}
for(const value of ['new','old'])document.getElementById(value).onclick=()=>setMode(value);
document.getElementById('outlines').onclick=event=>{visible=!visible;event.currentTarget.setAttribute('aria-pressed',String(visible));draw()};document.getElementById('only').onclick=event=>{only=!only;event.currentTarget.setAttribute('aria-pressed',String(only));draw()};document.getElementById('next').onclick=()=>{cursor=(cursor+1)%newHolds.length;show(newHolds[cursor],true)};document.getElementById('fit').onclick=()=>svg.setAttribute('viewBox','0 0 7292 5514');draw();
</script></html>'''
html=html.replace('__HOLDS__',json.dumps(holds,separators=(',',':')).replace('<','\\u003c')).replace('__NEW_IDS__',json.dumps(new))
archivehtml=html.replace('__IMAGE__','wall.jpg').replace('__REFERENCE__','../2026-11-v8-reviewed/wall.jpg').replace('__GIF__','comparisons/previous-vs-new.gif').replace('__PREVIEW__','comparisons/preview.jpg');(archive/'review.html').write_text(archivehtml)
publichtml=html.replace('__IMAGE__','wall.jpg').replace('__REFERENCE__','/wall/versions/2026-11-v8/wall.jpg').replace('__GIF__','previous-vs-new.gif').replace('__PREVIEW__','preview.jpg');(public/'index.html').write_text(publichtml)
for name,source in [('wall.jpg',archive/'wall.jpg'),('preview.jpg',archive/'comparisons/preview.jpg'),('previous-vs-new.gif',archive/'comparisons/previous-vs-new.gif')]:shutil.copy2(source,public/name)
(r/'viewer-template.html').write_text(html)
